task.starter_code:
// Платформа задаёт:
// const n = 5;
// const word = "JavaScript";
// Код проверят и на других значениях.

// 1. Таблица умножения для n: 10 строк "5 x 1 = 5"

// 2. let evenSum - сумма чётных чисел от 1 до n

// 3. let vowelCount - гласные a, e, i, o, u в word (for...of)

task.solution:
// 1. Таблица умножения
for (let i = 1; i <= 10; i++) {
    console.log(`${n} x ${i} = ${n * i}`);
}

// 2. Сумма чётных чисел от 1 до n
let evenSum = 0;
for (let i = 1; i <= n; i++) {
    if (i % 2 === 0) {
        evenSum += i;
    }
}

// 3. Гласные в слове
const vowels = "aeiou";
let vowelCount = 0;
for (const char of word) {
    if (vowels.includes(char.toLowerCase())) {
        vowelCount++;
    }
}

console.log(`Сумма чётных: ${evenSum}, гласных: ${vowelCount}`);

